"""Inspect synthetic artifacts generated by the focused browser verification."""
import json
import subprocess
from pathlib import Path
from zipfile import ZipFile
from xml.etree import ElementTree as ET

checks = []
for locale in ['en', 'ar']:
    path = Path('/tmp/narvo-source-assignment-' + locale)
    with ZipFile(str(path) + '.xlsx') as archive:
        sheet = ET.fromstring(archive.read('xl/worksheets/sheet1.xml'))
        ns = {'s': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
        if locale == 'ar':
            assert sheet.find('s:sheetViews/s:sheetView', ns).get('rightToLeft') in ['1', 'true']
        numeric = [cell.find('s:v', ns).text for cell in sheet.findall('.//s:c', ns)
                   if cell.find('s:v', ns) is not None and cell.get('t') not in ['s', 'inlineStr']]
        assert '125.5' in numeric
        if locale == 'en':
            assert '251' in numeric
        checks.append(locale + ' Excel numeric source amounts and selected total/RTL verified')
    text = subprocess.check_output(['pdftotext', '-layout', str(path) + '.pdf', '-']).decode()
    assert 'Synthetic assignment Company' in text and '125.50' in text
    assert '2026-09' in text
    if locale == 'en':
        assert 'Selected unposted' in text and 'source total' in text and '251.00' in text
        assert 'not posted project costs' in text
    checks.append(locale + ' PDF identity, period and exact source amounts verified')
Path('/tmp/narvo-source-assignment-exports.json').write_text(json.dumps({'status': 'PASS', 'checks': checks}, indent=2))
print('PASS: English/Arabic Excel numeric cells, RTL and PDF artifact contents')
